-- النسخة الإنجليزية: عمود i18n والمحتوى الإنجليزي الأولي. يُشغَّل مرة واحدة؛ إعادة التشغيل تُرفض تلقائياً بلا ضرر.
BEGIN;
DO $g$ BEGIN
  IF EXISTS (SELECT 1 FROM schema_migrations WHERE name = '047_i18n.sql') THEN
    RAISE EXCEPTION 'هذا الملف مطبّق من قبل، لا حاجة لتشغيله مرة ثانية. اضغطي ROLLBACK.';
  END IF;
END $g$;
-- النسخة الإنجليزية: عمود i18n في جداول المحتوى العام. الشكل: {"en": {...الحقول المترجمة...}}.
-- الحقول الناقصة في الترجمة تُعرض بالعربية. المحتوى الإنجليزي الأولي يُستورد من db/seed/source/en (scripts/seed.mjs)
-- وفي الإنتاج من db/updates/2026-10-24-i18n.sql.
ALTER TABLE products      ADD COLUMN IF NOT EXISTS i18n jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE faqs          ADD COLUMN IF NOT EXISTS i18n jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE policies      ADD COLUMN IF NOT EXISTS i18n jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS i18n jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE free_plans    ADD COLUMN IF NOT EXISTS i18n jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE booklets      ADD COLUMN IF NOT EXISTS i18n jsonb NOT NULL DEFAULT '{}'::jsonb;

-- الجداول المجانية تُحفظ عبر دالة، فالترجمة تحتاج صلاحية تحديث العمود فقط للمدربة
GRANT SELECT (i18n), UPDATE (i18n) ON free_plans TO nav_app;
DROP POLICY IF EXISTS free_plans_i18n ON free_plans;
CREATE POLICY free_plans_i18n ON free_plans FOR UPDATE USING (app.is_coach()) WITH CHECK (app.is_coach());

-- المحتوى الإنجليزي الأولي (يُكتب فقط حيث لا ترجمة بعد)
UPDATE products SET i18n = jsonb_set(i18n, '{en}', '{"name":"Intensive","audience":"Best for beginners and anyone who wants weekly follow-up with Zoom calls: training + nutrition + Zoom + one in-person session.","note":null,"delivery":"A personalised program file after the questionnaire, regular reviews by video or voice note, and daily contact on WhatsApp with replies within 48 working hours.","requirements":"Fill in the trainee questionnaire (5 steps), then transfer by bank and upload a photo of the receipt. The subscription starts once the transfer is verified and the questionnaire is complete.","policy_note":"Paid once per plan and duration by bank transfer, with no automatic renewal. 3-month subscriptions are covered by the conditional money-back guarantee and the free renewal for consistent trainees.","items":[{"text":"One free in-person session (1 hour) to correct technique and check exercise quality (women, Eastern Province)"},{"text":"A full training and nutrition plan with clear exercise guides, at home or in the gym"},{"text":"4 Zoom calls a month to review your progress and your training and mindset questions"},{"text":"A weekly review of your physical and mental progress (video or voice note), adjusting calories or training when needed"},{"text":"A simple guide to the MyFitnessPal calorie-tracking app"},{"text":"A complete training and nutrition booklet"},{"text":"Help choosing what suits your health and lifestyle in nutrition and daily routine"},{"text":"Daily contact, with replies within 48 working hours"}]}'::jsonb) WHERE slug = 'intensive' AND NOT (i18n ? 'en');
UPDATE products SET i18n = jsonb_set(i18n, '{en}', '{"name":"Advanced","audience":"For experienced trainees who want training + nutrition with weekly follow-up, without Zoom.","note":null,"delivery":"A personalised program file after the questionnaire, regular reviews by video or voice note, and daily contact on WhatsApp with replies within 48 working hours.","requirements":"Fill in the trainee questionnaire (5 steps), then transfer by bank and upload a photo of the receipt. The subscription starts once the transfer is verified and the questionnaire is complete.","policy_note":"Paid once per plan and duration by bank transfer, with no automatic renewal. 3-month subscriptions are covered by the conditional money-back guarantee and the free renewal for consistent trainees.","items":[{"text":"A full training and nutrition plan with clear exercise guides, at home or in the gym"},{"text":"A weekly review of your physical and mental progress (video or voice note), adjusting calories or training when needed"},{"text":"A complete training and nutrition booklet"},{"text":"Help choosing what suits your health and lifestyle in training and daily routine"},{"text":"Daily contact, with replies within 48 working hours"},{"text":"Zoom calls and the in-person session (Intensive only)"}]}'::jsonb) WHERE slug = 'advanced' AND NOT (i18n ? 'en');
UPDATE products SET i18n = jsonb_set(i18n, '{en}', '{"name":"Basic","audience":"For anyone who manages their own nutrition and needs a training plan only, with a review every two weeks.","note":null,"delivery":"A personalised program file after the questionnaire, regular reviews by video or voice note, and daily contact on WhatsApp with replies within 48 working hours.","requirements":"Fill in the trainee questionnaire (5 steps), then transfer by bank and upload a photo of the receipt. The subscription starts once the transfer is verified and the questionnaire is complete.","policy_note":"Paid once per plan and duration by bank transfer, with no automatic renewal. 3-month subscriptions are covered by the conditional money-back guarantee and the free renewal for consistent trainees.","items":[{"text":"A full training plan with clear exercise guides, at home or in the gym"},{"text":"A review every two weeks of your physical and mental progress (video or voice note), adjusting training when needed"},{"text":"A complete training and nutrition booklet"},{"text":"Daily contact, with replies within 48 working hours"},{"text":"No nutrition plan"}]}'::jsonb) WHERE slug = 'basic' AND NOT (i18n ? 'en');
UPDATE products SET i18n = jsonb_set(i18n, '{en}', '{"name":"Nutrition","audience":"For anyone who needs a complete nutrition plan and wants to learn calorie counting, without a training plan.","note":"One month · usually no renewal needed","delivery":"A personalised program file after the questionnaire, regular reviews by video or voice note, and daily contact on WhatsApp with replies within 48 working hours.","requirements":"Fill in the trainee questionnaire (5 steps), then transfer by bank and upload a photo of the receipt. The subscription starts once the transfer is verified and the questionnaire is complete.","policy_note":"Paid once by bank transfer, with no automatic renewal. The money-back guarantee covers 3-month subscriptions to Intensive, Advanced, and Basic only.","items":[{"text":"A complete nutrition plan that fits your goal and lifestyle"},{"text":"Your calorie target for your goal"},{"text":"Learning calorie counting, with food choices that suit you"},{"text":"An Excel file to track progress and measurements"},{"text":"A weekly discussion of your relationship with food at home and out"},{"text":"Daily contact, with replies within 48 working hours"},{"text":"Not needed if you are on Intensive or Advanced: nutrition is included there"}]}'::jsonb) WHERE slug = 'nutrition' AND NOT (i18n ? 'en');
UPDATE products SET i18n = jsonb_set(i18n, '{en}', '{"name":"Personal-training alternative","audience":"For advanced trainees who do not need follow-up, or as a cheaper alternative to personal training.","note":null,"delivery":"A personalised plan after the questionnaire, delivered as a file you can download to your device. No follow-up.","requirements":"Fill in the trainee questionnaire (5 steps), then transfer by bank and upload a photo of the receipt. The subscription starts once the transfer is verified and the questionnaire is complete.","policy_note":"Paid once by bank transfer. The plans are yours for life and you can edit them.","items":[{"text":"A custom training plan for the number of training days you need"},{"text":"How to gauge effort and the number of sets required"},{"text":"Download the plan to your device"}]}'::jsonb) WHERE slug = 'custom-training-plan' AND NOT (i18n ? 'en');
UPDATE products SET i18n = jsonb_set(i18n, '{en}', '{"name":"Training plan with nutrition","audience":"For advanced trainees who do not need follow-up, or as a cheaper alternative to personal training.","note":null,"delivery":"A personalised plan after the questionnaire, delivered as a file you can download to your device. No follow-up.","requirements":"Fill in the trainee questionnaire (5 steps), then transfer by bank and upload a photo of the receipt. The subscription starts once the transfer is verified and the questionnaire is complete.","policy_note":"Paid once by bank transfer. The plans are yours for life and you can edit them.","items":[{"text":"A custom training plan for the number of training days you need"},{"text":"How to gauge effort and the number of sets required"},{"text":"A nutrition plan with options that fit your training goal"},{"text":"Download the plan to your device"}]}'::jsonb) WHERE slug = 'training-nutrition-plan' AND NOT (i18n ? 'en');
UPDATE products SET i18n = jsonb_set(i18n, '{en}', '{"name":"Nutrition consultation","audience":"For specific nutrition questions: one session is enough to set your calories and food advice.","note":null,"delivery":"A session on Google Meet or WhatsApp, whichever suits you.","requirements":"Fill in the trainee questionnaire (5 steps), then transfer by bank and upload a photo of the receipt. The subscription starts once the transfer is verified and the questionnaire is complete.","policy_note":"Paid once by bank transfer.","items":[{"text":"Discuss all your nutrition questions"},{"text":"A calorie target for your goal with food suggestions"},{"text":"Advice on supplements and how to eat out the right way"}]}'::jsonb) WHERE slug = 'nutrition-consultation' AND NOT (i18n ? 'en');
UPDATE products SET i18n = jsonb_set(i18n, '{en}', '{"name":"Training consultation","audience":"For specific training questions: one session is enough to adjust your plan and correct technique.","note":null,"delivery":"A session on Google Meet or WhatsApp, whichever suits you.","requirements":"Fill in the trainee questionnaire (5 steps), then transfer by bank and upload a photo of the receipt. The subscription starts once the transfer is verified and the questionnaire is complete.","policy_note":"Paid once by bank transfer.","items":[{"text":"Discuss all your training questions"},{"text":"Adjust your training plan to your goal, with mobility exercise suggestions"},{"text":"Correct the technique of exercises you suspect are wrong or cause pain"},{"text":"Check that your training quality is right for building muscle"}]}'::jsonb) WHERE slug = 'training-consultation' AND NOT (i18n ? 'en');
UPDATE faqs SET i18n = jsonb_set(i18n, '{en}', '{"question":"When do I hear back after subscribing?","answer":"Within 48 working hours. Working days are Sunday to Thursday, 12 pm to 9 pm, and contact is on WhatsApp."}'::jsonb) WHERE question = 'متى يوصلني الرد بعد الاشتراك؟' AND NOT (i18n ? 'en');
UPDATE faqs SET i18n = jsonb_set(i18n, '{en}', '{"question":"How does follow-up work?","answer":"You send the weekly review on your review day, and I reply with recorded adjustments (video or voice). On the Basic plan the review is every two weeks. Daily contact is on WhatsApp, with replies within 48 hours."}'::jsonb) WHERE question = 'كيف تتم المتابعة؟' AND NOT (i18n ? 'en');
UPDATE faqs SET i18n = jsonb_set(i18n, '{en}', '{"question":"Is it suitable for complete beginners?","answer":"Yes. The program is built on your current level, every exercise is explained, and you can send clips of your form for technique correction."}'::jsonb) WHERE question = 'هل يناسب المبتدئين تماماً؟' AND NOT (i18n ? 'en');
UPDATE faqs SET i18n = jsonb_set(i18n, '{en}', '{"question":"I train at home. What equipment do I need?","answer":"The questionnaire has a field for the equipment you have (dumbbells, resistance bands, barbell…) and your plan is built around it."}'::jsonb) WHERE question = 'أتمرن في البيت، ماذا أحتاج من أدوات؟' AND NOT (i18n ? 'en');
UPDATE faqs SET i18n = jsonb_set(i18n, '{en}', '{"question":"How do I pay?","answer":"By bank transfer after filling in the questionnaire. As soon as you submit it, your order number, the amount, and the account details appear. Transfer the amount, then upload a photo of the receipt from your order page. Your subscription is confirmed once the payment is verified."}'::jsonb) WHERE question = 'كيف أدفع؟' AND NOT (i18n ? 'en');
UPDATE faqs SET i18n = jsonb_set(i18n, '{en}', '{"question":"What are the money-back guarantee conditions?","answer":"On 3-month subscriptions to the follow-up plans (Intensive, Advanced, Basic): if none of your progress indicators improves after 12 weeks, the full amount is refunded.\nProgress indicators (by goal): weekly average weight, waist circumference, or strength in the main lifts (weight or reps).\nGuarantee conditions:\n- Send the weekly review every week.\n- Take measurements regularly.\n- Film your exercises and send them.\n- Follow the custom nutrition plan (on plans that include nutrition).\nRequest the refund on WhatsApp within 14 days of the end of the three months."}'::jsonb) WHERE question = 'ما شروط ضمان استرجاع المبلغ؟' AND NOT (i18n ? 'en');
UPDATE faqs SET i18n = jsonb_set(i18n, '{en}', '{"question":"Do I keep the plans after my subscription ends?","answer":"Yes. All plans are yours for life, and you can edit them."}'::jsonb) WHERE question = 'هل الجداول لي بعد انتهاء الاشتراك؟' AND NOT (i18n ? 'en');
UPDATE faqs SET i18n = jsonb_set(i18n, '{en}', '{"question":"What is the free renewal?","answer":"A reward for consistency: a 3-month subscription earns 3 extra months free, so you get 6 months for the price of 3.\nConditions:\n- Adherence of 90% or more: weekly reviews sent and workouts logged.\n- Clear progress in the same indicators listed in the guarantee.\n- Male trainees: send before-and-after photos to the coach for documentation, with face and navel covered.\nPosting photos on social media is entirely optional and does not affect your eligibility."}'::jsonb) WHERE question = 'ما هو التجديد المجاني؟' AND NOT (i18n ? 'en');
UPDATE faqs SET i18n = jsonb_set(i18n, '{en}', '{"question":"Who can see my data?","answer":"Only the coach, and it is used to design your program and follow up with you. Your results or photos are never published without your explicit consent in the form."}'::jsonb) WHERE question = 'من يطّلع على بياناتي؟' AND NOT (i18n ? 'en');
UPDATE policies SET i18n = jsonb_set(i18n, '{en}', '{"title":"Terms and conditions","body":"- “Trainee” means anyone of either gender who subscribes to the service.\n- The subscription starts after the bank transfer is verified and the trainee questionnaire is completed.\n- Working hours: Sunday to Thursday, 12 pm to 9 pm. Messages are answered within 48 working hours.\n- The program is not a substitute for medical advice. The trainee is responsible for disclosing any injury or health condition.\n- Plans belong to the trainee for life and can be edited.\n- Payment is made once per plan and duration by bank transfer. There is no automatic renewal."}'::jsonb) WHERE slug = 'terms' AND NOT (i18n ? 'en');
UPDATE policies SET i18n = jsonb_set(i18n, '{en}', '{"title":"Guarantee and refunds","body":"- On 3-month subscriptions to the follow-up plans (Intensive, Advanced, Basic): the full amount is refunded if none of the progress indicators (weekly average weight, waist circumference, strength in the main lifts) improves after 12 weeks.\n- Guarantee conditions: send the weekly review every week, take measurements regularly, film and send your exercises, and follow the custom nutrition plan on plans that include it.\n- Request the refund on WhatsApp within 14 days of the end of the three months. The amount is returned by bank transfer.\n- Free renewal: a 3-month subscription is rewarded with 3 extra months when adherence is 90% or more and progress is clear in the progress indicators. Progress photos are sent to the coach for documentation (men: face and navel covered), and publishing them is optional."}'::jsonb) WHERE slug = 'refund' AND NOT (i18n ? 'en');
UPDATE policies SET i18n = jsonb_set(i18n, '{en}', '{"title":"Privacy policy","body":"- We collect: your name, email (to sign in), mobile number (WhatsApp), the chosen plan, and the questionnaire answers you write yourself (including optional health information and measurements).\n- Purpose: to fulfil your order, design your program, follow up with you, and contact you about it only.\n- Health information is stored separately, is visible only to you and the coach, and is never sent in emails or notifications.\n- Payment is by direct bank transfer to the establishment’s account. The site never asks for or stores bank or card details. The transfer receipt is used only to confirm your order and is kept in private storage that only you and the coach can open.\n- We do not sell your data or share it for marketing. Your results or photos are never published without your explicit consent.\n- You can request a copy of your data, its deletion, or withdraw consent to publishing by messaging us on WhatsApp.\n- Analytics: we use Google Analytics on the public pages only, and only after you accept the banner on your first visit; declining means the visit is not measured. It never runs inside your account or on order, payment, or program pages, is never linked to your health or personal data, and is not used for advertising. Analytics data is processed by Google and is largely anonymised (IP masked, no personalised-ads features). Clearing the site data in your browser withdraws consent and shows the banner again."}'::jsonb) WHERE slug = 'privacy' AND NOT (i18n ? 'en');
UPDATE policies SET i18n = jsonb_set(i18n, '{en}', '{"title":"Reviews policy","body":"- Only trainees who bought a service and actually started it can write a review: one review per order.\n- Every review is checked before it appears publicly, and its text is never edited.\n- How your name appears is your choice: full name, first name only, or no name. Consent to publish is separate and optional.\n- Reviews containing phone numbers, emails, links, private health details, or abuse of any person are not published.\n- The coach may reply to a review, or hide a review that breaks this policy and record the reason.\n- You can ask for your review to be hidden at any time by messaging us on WhatsApp."}'::jsonb) WHERE slug = 'reviews' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '{"eyebrow":"Nav Coaching · Coach Sara","title":"A program built around you,","title_tail":"not a template","lead":"Personalised training and nutrition for your goal and level, reviewed and adjusted every week by Coach Sara.","tagline":"Where Passion Meets Quality"}'::jsonb) WHERE key = 'hero' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '["Coaching since 2017","MSc Sports Coaching · University of Stirling","Conditional money-back guarantee"]'::jsonb) WHERE key = 'badges' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '[{"title":"Built on your goal and level","body":"The program is designed after a detailed questionnaire about your goal, available days, equipment, and any injury that needs care."},{"title":"Clear weekly follow-up","body":"Regular reviews by video or voice, and daily contact on WhatsApp with replies within 48 working hours."},{"title":"Adjusted to your progress","body":"We adjust training and calories based on your measurements and adherence, so the results last."}]'::jsonb) WHERE key = 'why' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '[{"title":"Choose a program and fill in the questionnaire","body":"Pick the plan and duration, then a short questionnaire about your goal, level, available days, and any injury."},{"title":"Transfer the payment","body":"After the questionnaire, your order number and the account details appear. Transfer, then upload a photo of the receipt from your order page."},{"title":"Receive your program and start","body":"Once the transfer is verified I get in touch within 48 working hours, your program file is delivered, and follow-up begins."}]'::jsonb) WHERE key = 'how_steps' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '{"name":"Coach Sara | Nav","bio":"Certified personal trainer, coaching since 2017. I help you build a clear training and nutrition routine that fits your goal, time, and level, with weekly follow-up that keeps you going and progressing.","home_bio":"Certified personal trainer, coaching since 2017, and former captain of the basketball team at Imam Abdulrahman Bin Faisal University. I help you build a clear training and nutrition routine that fits your goal, time, and level, with weekly follow-up and no restrictive diets.","points":["A program built on your goal and level.","Clear weekly follow-up.","Continuous adjustments to your progress and adherence."],"story_title":"I became the person I once needed","story":["Before I became a coach, I was a trainee tired of experiments. I subscribed with coaches abroad and never found anyone who explained the exercises properly or cared about my goals.","Then I trained with Coach Sahar Alharthi. She changed how I saw training and inspired me to become a coach, and to this day I thank her for everything she taught me. That is when I decided to be the person I had needed.","Sport has been part of me from early on: I played basketball and captained the team at Imam Abdulrahman Bin Faisal University, and I competed professionally in esports. I started coaching in 2017 with basketball, worked as an assistant coach at the university club, and then coached at Pure Gym, Gymnation, Fitness Lounge, and private clubs."],"pillars_title":"What makes training with me different?","pillars":[{"title":"Your plan explained on video","body":"I do not send a plan and leave it there. I walk through it with you in a video explaining everything, so you start with full understanding: what we do and why."},{"title":"No deprivation","body":"I never use restrictive diets. Your plan fits your life, not a list of banned foods."},{"title":"Serious follow-up, realistic plan","body":"I check in with you every week, care about your adherence, and adjust your plan to your progress and circumstances."},{"title":"I teach you, not just train you","body":"I have loved teaching since I was young. I share everything I know, the science and the mindset, and I never stop researching and learning so that we both improve."}],"fit_title":"Who I work best with","fit":["Anyone who believes training is a lifestyle, not a quick fix for a temporary look or just for summer.","**And if adherence slips?** I try to understand why and help you work through it as much as I can. If it is bigger than what I can offer, I say so honestly and step back from coaching you."],"notes":[{"title":"For gamers","body":"Coming from the esports world, I designed a special plan for gamers: better fitness on and off the screen, and dealing with back and joint pain from long sitting.","href":"/programs/gamers","label":"Gamers plan →"},{"title":"During pregnancy","body":"I coach pregnant trainees in person only. Online, I cannot be sure every exercise is performed correctly, and pregnancy is a time that needs that certainty. Online, I offer nutrition follow-up only during pregnancy.","href":"","label":""}],"experience_title":"Qualifications and experience","experience":["Coaching since 2017, starting in basketball.","Assistant coach at the university club.","Coach at Pure Gym, Gymnation, Fitness Lounge, and private clubs."],"certs":["Saudi Reps — Level 4","NCSF","Menno Henselmans CPT","Functional Mobility","Pre & Postnatal Training","Prenatal Fitness Training — Aspire Academy","MSc Sports Coaching — University of Stirling"]}'::jsonb) WHERE key = 'about' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '"Experiences are personal and results vary from person to person depending on adherence and condition. Coaching is not a substitute for a doctor or physiotherapist."'::jsonb) WHERE key = 'testimonials_disclaimer' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '"Prices are in Saudi riyals. Payment by bank transfer to the establishment’s account."'::jsonb) WHERE key = 'prices_note' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '"within 48 working hours (Sunday to Thursday, 12 pm to 9 pm)"'::jsonb) WHERE key = 'response_time' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '{"name":"Nav Coaching for Sports Training Est."}'::jsonb) WHERE key = 'legal' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '{"accountName":"Nav Coaching for Sports Training Est.","bankName":"Al Rajhi Bank"}'::jsonb) WHERE key = 'bank' AND NOT (i18n ? 'en');
UPDATE site_settings SET i18n = jsonb_set(i18n, '{en}', '[{"title":"My program","caption":"As soon as you open your account: your adherence and streak, this week’s training days, today’s nutrition against your targets, and your supplement routine.","alt":"Screenshot of the account page with sample data: adherence bar, this week’s training days, today’s nutrition summary, and supplement routine"},{"title":"Workout log","caption":"Each exercise shows the target sets, reps, and RIR; you log your weight and reps from your phone, and can swap in an alternative chosen by the coach.","alt":"Screenshot of the training program page with sample data: weekdays and an exercise card with targets and fields for weight, reps, and RIR"},{"title":"Daily nutrition","caption":"Your daily calorie and macro targets and what is left, logging food from your meal plans or by the gram from the food database.","alt":"Screenshot of the nutrition page with sample data: today’s summary against targets, an add-food form, and today’s food by meal"},{"title":"Progress dashboard","caption":"Your weight and measurements in clear week-by-week charts, with sample data.","alt":"Screenshot of the progress dashboard with sample data: weight chart and measurements chart"}]'::jsonb) WHERE key = 'program_shots' AND NOT (i18n ? 'en');
INSERT INTO schema_migrations (name) VALUES ('047_i18n.sql');
COMMIT;
